package de.teamlapen.vampirism.common.world.entity;

import de.teamlapen.faction.FactionsMod;
import de.teamlapen.faction.api.factions.IFaction;
import de.teamlapen.faction.api.factions.IFactionEntity;
import de.teamlapen.faction.api.factions.IPlayableFaction;
import de.teamlapen.faction.api.world.entities.IEntityWithHome;
import de.teamlapen.faction.api.world.entities.extensions.ILivingEntity;
import de.teamlapen.faction.common.config.FactionConfig;
import de.teamlapen.faction.common.factions.FactionPlayerHandler;
import de.teamlapen.faction.common.util.SpawnUtil;
import de.teamlapen.vampirism.api.util.VIdentifier;
import de.teamlapen.vampirism.api.world.entity.IVampirismEntity;
import de.teamlapen.vampirism.common.core.ModParticles;
import de.teamlapen.vampirism.common.particles.GenericParticleOptions;
import de.teamlapen.vampirism.common.tags.ModBiomeTags;
import de.teamlapen.vampirism.common.world.attachments.LevelFog;
import net.minecraft.core.BlockPos;
import net.minecraft.core.Holder;
import net.minecraft.network.chat.Component;
import net.minecraft.server.level.ServerLevel;
import net.minecraft.sounds.SoundEvent;
import net.minecraft.sounds.SoundEvents;
import net.minecraft.util.Mth;
import net.minecraft.util.ProblemReporter;
import net.minecraft.world.Difficulty;
import net.minecraft.world.damagesource.DamageSource;
import net.minecraft.world.entity.*;
import net.minecraft.world.entity.ai.attributes.AttributeSupplier;
import net.minecraft.world.entity.ai.attributes.Attributes;
import net.minecraft.world.entity.ai.goal.Goal;
import net.minecraft.world.entity.ai.goal.MoveTowardsRestrictionGoal;
import net.minecraft.world.entity.monster.Enemy;
import net.minecraft.world.entity.player.Player;
import net.minecraft.world.level.Level;
import net.minecraft.world.level.LevelAccessor;
import net.minecraft.world.level.LightLayer;
import net.minecraft.world.level.storage.TagValueInput;
import net.minecraft.world.level.storage.TagValueOutput;
import net.minecraft.world.level.storage.ValueInput;
import net.minecraft.world.level.storage.ValueOutput;
import net.minecraft.world.phys.AABB;
import net.minecraft.world.phys.Vec3;
import net.neoforged.neoforge.server.ServerLifecycleHooks;
import org.jetbrains.annotations.NotNull;
import org.jetbrains.annotations.Nullable;

/**
 * Base class for most vampirism mobs
 */
public abstract class VampirismEntity extends PathfinderMob implements IEntityWithHome, IVampirismEntity, ILivingEntity {

    public static boolean spawnPredicateVampireFog(@NotNull LevelAccessor world, @NotNull BlockPos blockPos) {
        return world.getBiome(blockPos).is(ModBiomeTags.HasFaction.IS_VAMPIRE_BIOME) || (world instanceof Level && LevelFog.get((Level) world).isInsideArtificialVampireFogArea(blockPos));
    }

    public static AttributeSupplier.@NotNull Builder getAttributeBuilder() {
        return PathfinderMob.createLivingAttributes().add(Attributes.ATTACK_DAMAGE).add(Attributes.FOLLOW_RANGE, 16).add(Attributes.ATTACK_KNOCKBACK);
    }

    private final @NotNull Goal moveTowardsRestriction;
    protected boolean hasArms = true;
    protected boolean peaceful = false;
    /**
     * Whether the home should be saved to nbt or not
     */
    protected boolean saveHome = false;
    @Nullable
    private AABB home;
    private boolean moveTowardsRestrictionAdded = false;
    private int moveTowardsRestrictionPrio = -1;
    /**
     * Counter which reaches zero every 70 to 120 ticks
     */
    private int randomTickDivider;
    private boolean doImobConversion = false;

    public VampirismEntity(@NotNull EntityType<? extends VampirismEntity> type, @NotNull Level world) {
        super(type, world);
        moveTowardsRestriction = new MoveTowardsRestrictionGoal(this, 1.0F);
    }

    @Override
    public void addAdditionalSaveData(@NotNull ValueOutput output) {
        super.addAdditionalSaveData(output);
        if (saveHome && home != null) {
            int[] h = {(int) home.minX, (int) home.minY, (int) home.minZ, (int) home.maxX, (int) home.maxY, (int) home.maxZ};
            output.putIntArray("home", h);
            if (moveTowardsRestrictionAdded && moveTowardsRestrictionPrio > -1) {
                output.putInt("homeMovePrio", moveTowardsRestrictionPrio);
            }
        }
    }

    @Nullable
    @Override
    public AABB getHome() {
        return home;
    }

    @Override
    public void aiStep() {
        if (hasArms) {
            this.updateSwingTime();
        }
        super.aiStep();
    }

    @Override
    public boolean checkSpawnRules(@NotNull LevelAccessor worldIn, @NotNull EntitySpawnReason spawnReasonIn) {
        return (peaceful || worldIn.getDifficulty() != Difficulty.PEACEFUL) && super.checkSpawnRules(worldIn, spawnReasonIn);
    }

    @Override
    public boolean isWithinHomeDistance(double x, double y, double z) {
        if (home != null) {
            return home.contains(new Vec3(x, y, z));
        }
        return true;
    }

    @Override
    public void readAdditionalSaveData(@NotNull ValueInput input) {
        super.readAdditionalSaveData(input);
        input.getIntArray("home").ifPresent(h -> {
            this.setHome(new AABB(h[0], h[1], h[2], h[3], h[4], h[5]));
            input.getInt("homeMovePrio").ifPresent(x -> this.setMoveTowardsRestriction(x, true));
        });
    }

    @Override
    public void setHome(@Nullable AABB home) {
        this.home = home;
        if (home != null) {
            int posX, posY, posZ;
            posX = (int) (home.minX + (home.maxX - home.minX) / 2);
            posY = (int) (home.minY + (home.maxY - home.minY) / 2);
            posZ = (int) (home.minZ + (home.maxZ - home.minZ) / 2);
            super.setHomeTo(new BlockPos(posX, posY, posZ), (int) home.getSize());
        } else {
            super.setHomeTo(new BlockPos(0, 0, 0), -1);
        }
    }

    @Override
    public void setHomeArea(@NotNull BlockPos pos, int r) {
        this.setHome(new AABB(Vec3.atLowerCornerOf(pos.offset(-r, -r, -r)), Vec3.atLowerCornerWithOffset(pos.offset(r, r, r), 1, 1, 1)));
    }

    @Override
    public void tick() {
        super.tick();
        this.checkImobConversion();
        if (!this.level().isClientSide() && !peaceful && this.level().getDifficulty() == Difficulty.PEACEFUL) {
            this.discard();
        }
    }

    @Override
    protected void customServerAiStep(ServerLevel level) {
        super.customServerAiStep(level);
        if (--this.randomTickDivider <= 0) {
            this.randomTickDivider = 70 + random.nextInt(50);
            onRandomTick();
        }
    }

    protected void disableImobConversion() {
        this.doImobConversion = false;
    }

    /**
     * Removes the MoveTowardsRestriction task
     */
    protected void disableMoveTowardsRestriction() {
        if (moveTowardsRestrictionAdded) {
            this.goalSelector.removeGoal(moveTowardsRestriction);
            moveTowardsRestrictionAdded = false;
        }
    }

    protected void enableImobConversion() {
        if (this instanceof IFactionEntity) {
            this.doImobConversion = true;
        } else {
            throw new IllegalStateException("Can only do IMob conversion for IFactionEntity");
        }
    }

    protected SoundEvent getDeathSound() {
        return SoundEvents.HOSTILE_DEATH;
    }

    @NotNull
    @Override
    public LivingEntity.Fallsounds getFallSounds() {
        return new LivingEntity.Fallsounds(SoundEvents.HOSTILE_SMALL_FALL, SoundEvents.HOSTILE_BIG_FALL);
    }

    @Nullable
    @Override
    protected SoundEvent getHurtSound(DamageSource source) {
        return SoundEvents.HOSTILE_HURT;
    }

    /**
     * @param iMob Whether we want the iMob or non iMob variant
     * @return Must be LivingEntity type
     */
    protected @NotNull EntityType<?> getIMobTypeOpt(boolean iMob) {
        return this.getType();
    }

    /**
     * IMob variants should have the same names as their non-IMob variants, that's why this is resolved here.
     */
    @Override
    protected @NotNull Component getTypeName() {
        return getIMobTypeOpt(false).getDescription();
    }

    @NotNull
    @Override
    protected SoundEvent getSwimSound() {
        return SoundEvents.HOSTILE_SWIM;
    }

    @NotNull
    @Override
    protected SoundEvent getSwimSplashSound() {
        return SoundEvents.HOSTILE_SPLASH;
    }

    protected boolean isLowLightLevel(@NotNull LevelAccessor iWorld) {
        //copy of Monster#isDarkEnoughToSSpawn, but not requiring server level
        BlockPos blockpos = new BlockPos((int) this.getX(), (int) this.getBoundingBox().minY, (int) this.getZ());
        if (iWorld.getBrightness(LightLayer.SKY, blockpos) > this.random.nextInt(32)) {
            return false;
        } else if (iWorld.getBrightness(LightLayer.BLOCK, blockpos) > 0) {
            return false;
        } else {
            int i = iWorld.getMaxLocalRawBrightness(blockpos);

            if (iWorld instanceof Level && ((Level) iWorld).isThundering()) {
                i = iWorld.getMaxLocalRawBrightness(blockpos);
            }

            return i <= this.random.nextInt(8);
        }
    }

    @Override
    public @NotNull LivingEntity asEntity() {
        return this;
    }

    /**
     * Called every 70 to 120 ticks during {@link Mob#customServerAiStep(ServerLevel)}
     */
    @SuppressWarnings("EmptyMethod")
    protected void onRandomTick() {

    }

    protected void setDontDropEquipment() {
    }

    /**
     * Add the MoveTowardsRestriction task with the given priority.
     * Overrides prior priorities if existent
     * e
     *
     * @param prio   Priority of the task
     * @param active If the task should be active or not
     */
    protected void setMoveTowardsRestriction(int prio, boolean active) {
        if (moveTowardsRestrictionAdded) {
            if (active && moveTowardsRestrictionPrio == prio) {
                return;
            }
            this.goalSelector.removeGoal(moveTowardsRestriction);
            moveTowardsRestrictionAdded = false;
        }
        if (active) {
            goalSelector.addGoal(prio, moveTowardsRestriction);
            moveTowardsRestrictionAdded = true;
            moveTowardsRestrictionPrio = prio;
        }

    }

    @Override
    public boolean shouldDropExperience() {
        return true;
    }

    /**
     * Fakes a teleportation and actually just kills the entity
     */
    protected void teleportAway() {
        this.setInvisible(true);
        ModParticles.spawnParticlesServer(this.level(), new GenericParticleOptions(VIdentifier.mc("effect_6"), 10, 0x0A0A0A, 0.6F), this.getX(), this.getY(), this.getZ(), 20, 1, 1, 1, 0);
        this.playSound(SoundEvents.ENDERMAN_TELEPORT, 1, 1);
        this.discard();
    }

    private void checkImobConversion() {
        if (doImobConversion && !this.level().isClientSide()) {
            if (this.tickCount % 256 == 0 && this.isAlive()) {
                boolean current = this instanceof Enemy;
                boolean convert = false;
                de.teamlapen.faction.common.config.ServerConfig.IMobOptions opt = FactionConfig.server().entitiesIMob.get();
                if (ServerLifecycleHooks.getCurrentServer().isDedicatedServer()) {
                    convert = (opt == de.teamlapen.faction.common.config.ServerConfig.IMobOptions.ALWAYS_IMOB) != current;
                } else {
                    if (opt == de.teamlapen.faction.common.config.ServerConfig.IMobOptions.SMART) {
                        Player player = FactionsMod.proxy.getClientPlayer();
                        if (player != null && player.isAlive()) {
                            Holder<? extends IPlayableFaction<?>> f = FactionPlayerHandler.get(player).getFaction();
                            Holder<IFaction<?>> thisFaction = (Holder<IFaction<?>>) ((IFactionEntity) this).getFaction();

                            boolean hostile = IFaction.isNeutral(f) ? thisFaction.is(de.teamlapen.faction.api.tags.FactionTags.HOSTILE_TOWARDS_NEUTRAL) : !thisFaction.equals(f);
                            convert = hostile != current;

                        }
                    } else {
                        convert = (opt == de.teamlapen.faction.common.config.ServerConfig.IMobOptions.ALWAYS_IMOB) != current;
                    }
                }
                if (convert) {
                    EntityType<?> t = getIMobTypeOpt(!current);
                    SpawnUtil.createEntity(t, this.level(), EntitySpawnReason.CONVERSION).ifPresent(newEntity -> {
                        TagValueOutput withContext = TagValueOutput.createWithContext(ProblemReporter.DISCARDING, this.registryAccess());
                        this.saveWithoutId(withContext);
                        newEntity.load(TagValueInput.create(ProblemReporter.DISCARDING, this.registryAccess(), withContext.buildResult()));
                        newEntity.setUUID(Mth.createInsecureUUID(this.random));
                        assert newEntity instanceof LivingEntity;
                        SpawnUtil.replaceEntity(this, (LivingEntity) newEntity);
                    });

                }
            }
        }
    }

    @Override
    public boolean canBeLeashed() {
        return false;
    }
}

package de.teamlapen.vampirism.common.world.entity.hunter;

import de.teamlapen.faction.api.factions.IFactionPredicate;
import de.teamlapen.faction.api.world.ICaptureAttributes;
import de.teamlapen.vampirism.VampirismMod;
import de.teamlapen.vampirism.api.difficulty.Difficulty;
import de.teamlapen.vampirism.api.world.entity.VampireBookLootProvider;
import de.teamlapen.vampirism.api.world.entity.hunter.IAdvancedHunter;
import de.teamlapen.vampirism.api.world.entity.hunter.IVampirismCrossbowUser;
import de.teamlapen.vampirism.api.world.items.IHunterCrossbow;
import de.teamlapen.vampirism.api.world.items.components.IVampireBook;
import de.teamlapen.vampirism.common.config.BalanceMobProps;
import de.teamlapen.vampirism.common.core.ModAttachments;
import de.teamlapen.vampirism.common.core.ModEntities;
import de.teamlapen.vampirism.common.core.ModItems;
import de.teamlapen.vampirism.common.util.UtilLib;
import de.teamlapen.vampirism.common.world.entity.ISupporterAppearanceConsumer;
import de.teamlapen.vampirism.common.world.entity.VampirismEntity;
import de.teamlapen.vampirism.common.world.entity.ai.goals.*;
import de.teamlapen.vampirism.common.world.entity.ai.navigation.HunterPathNavigation;
import de.teamlapen.vampirism.common.world.entity.vampire.VampireBaseEntity;
import net.minecraft.core.Holder;
import net.minecraft.core.registries.BuiltInRegistries;
import net.minecraft.network.syncher.EntityDataAccessor;
import net.minecraft.network.syncher.EntityDataSerializers;
import net.minecraft.network.syncher.SynchedEntityData;
import net.minecraft.server.level.ServerLevel;
import net.minecraft.tags.StructureTags;
import net.minecraft.world.DifficultyInstance;
import net.minecraft.world.InteractionHand;
import net.minecraft.world.InteractionResult;
import net.minecraft.world.effect.MobEffectInstance;
import net.minecraft.world.effect.MobEffects;
import net.minecraft.world.entity.*;
import net.minecraft.world.entity.ai.attributes.AttributeSupplier;
import net.minecraft.world.entity.ai.attributes.Attributes;
import net.minecraft.world.entity.ai.goal.*;
import net.minecraft.world.entity.ai.goal.target.NearestAttackableTargetGoal;
import net.minecraft.world.entity.ai.navigation.PathNavigation;
import net.minecraft.world.entity.monster.PatrollingMonster;
import net.minecraft.world.entity.monster.zombie.Zombie;
import net.minecraft.world.entity.player.Player;
import net.minecraft.world.item.Item;
import net.minecraft.world.item.ItemStack;
import net.minecraft.world.level.Level;
import net.minecraft.world.level.ServerLevelAccessor;
import net.minecraft.world.level.storage.ValueInput;
import net.minecraft.world.level.storage.ValueOutput;
import net.minecraft.world.phys.AABB;
import org.jetbrains.annotations.NotNull;
import org.jetbrains.annotations.Nullable;
import org.jspecify.annotations.NonNull;

import javax.annotation.Nonnull;
import java.util.Optional;

/**
 * Advanced hunter. Is strong. Represents supporters
 */
public class AdvancedHunterEntity extends HunterBaseEntity implements IAdvancedHunter, VampireBookLootProvider, IVampirismCrossbowUser, ISupporterAppearanceConsumer {
    private static final EntityDataAccessor<Integer> LEVEL = SynchedEntityData.defineId(AdvancedHunterEntity.class, EntityDataSerializers.INT);
    private static final EntityDataAccessor<Boolean> IS_CHARGING_CROSSBOW = SynchedEntityData.defineId(AdvancedHunterEntity.class, EntityDataSerializers.BOOLEAN);
    public static final EntityDataAccessor<Holder<Item>> SPECIAL_ARROW = SynchedEntityData.defineId(AdvancedHunterEntity.class, ModEntities.ITEM_HOLDER.get());

    private static final int MAX_LEVEL = 1;
    private static final int MOVE_TO_RESTRICT_PRIO = 3;

    public static AttributeSupplier.@NotNull Builder getAttributeBuilder() {
        return VampirismEntity.getAttributeBuilder()
                .add(Attributes.MAX_HEALTH, BalanceMobProps.mobProps.ADVANCED_HUNTER_MAX_HEALTH)
                .add(Attributes.ATTACK_DAMAGE, BalanceMobProps.mobProps.ADVANCED_HUNTER_ATTACK_DAMAGE)
                .add(Attributes.MOVEMENT_SPEED, BalanceMobProps.mobProps.ADVANCED_HUNTER_SPEED);
    }

    private boolean attack;
    @Nullable
    private ICaptureAttributes villageAttributes;

    public AdvancedHunterEntity(EntityType<? extends AdvancedHunterEntity> type, Level world) {
        super(type, world);
        saveHome = true;
        this.getNavigation().setCanOpenDoors(true);


        this.setDontDropEquipment();
        this.enableImobConversion();
    }

    @Override
    public void addAdditionalSaveData(@NotNull ValueOutput output) {
        super.addAdditionalSaveData(output);
        output.putInt("level", getEntityLevel());
        output.putBoolean("attack", attack);
        output.store("specialArrow", BuiltInRegistries.ITEM.holderByNameCodec(), getEntityData().get(SPECIAL_ARROW));
    }

    @Override
    public void attackVillage(@NonNull ICaptureAttributes attributes) {
        this.villageAttributes = attributes;
        this.attack = true;
    }

    @Override
    public void defendVillage(@NonNull ICaptureAttributes attributes) {
        this.villageAttributes = attributes;
        this.attack = false;
    }

    @Override
    public boolean doHurtTarget(ServerLevel level, @NotNull Entity entity) {
        boolean flag = super.doHurtTarget(level, entity);
        if (flag && this.getMainHandItem().isEmpty()) {
            this.swing(InteractionHand.MAIN_HAND);  //Swing stake if nothing else is held
        }
        return flag;
    }

    @Override
    public @NotNull Optional<Holder<IVampireBook>> getBookLootId() {
        return getData(ModAttachments.SUPPORTER).book();
    }

    @Nullable
    @Override
    public ICaptureAttributes getCaptureInfo() {
        return this.villageAttributes;
    }

    @Override
    public int getEntityLevel() {
        return getEntityData().get(LEVEL);
    }

    @Override
    public void setEntityLevel(int level) {
        if (level >= 0) {
            getEntityData().set(LEVEL, level);
            this.updateEntityAttributes();
            if (level == 1) {
                this.addEffect(new MobEffectInstance(MobEffects.RESISTANCE, 1000000, 1, false, false));
            }

        }
    }

    @Override
    public int getMaxEntityLevel() {
        return MAX_LEVEL;
    }

    @Nullable
    @Override
    public AABB getTargetVillageArea() {
        return villageAttributes == null ? null : villageAttributes.getVillageArea();
    }

    @Override
    public boolean isAttackingVillage() {
        return villageAttributes != null && attack;
    }

    @Override
    public boolean isDefendingVillage() {
        return villageAttributes != null && !attack;
    }

    @Override
    public boolean isLookingForHome() {
        return getHome() == null;
    }

    @Override
    public void readAdditionalSaveData(@NotNull ValueInput input) {
        super.readAdditionalSaveData(input);
        input.getInt("level").ifPresent(this::setEntityLevel);
        this.attack = input.getBooleanOr("attack", false);
        input.read("specialArrow", BuiltInRegistries.ITEM.holderByNameCodec()).ifPresent(x -> this.getEntityData().set(SPECIAL_ARROW, x));
    }

    @Override
    public boolean removeWhenFarAway(double distanceToClosestPlayer) {
        return super.removeWhenFarAway(distanceToClosestPlayer) && isLookingForHome();
    }

    @Override
    public void setCampArea(AABB box) {
        super.setHome(box);
        this.setMoveTowardsRestriction(MOVE_TO_RESTRICT_PRIO, true);
    }

    @Override
    public void stopVillageAttackDefense() {
        this.setCustomName(null);
        this.villageAttributes = null;
    }

    @Override
    public boolean shouldShowName() {
        return true;
    }

    @Override
    public int suggestEntityLevel(@NotNull Difficulty d) {
        if (random.nextBoolean()) {
            return (int) (d.avgPercLevel() * MAX_LEVEL / 100F);
        }
        return random.nextInt(MAX_LEVEL + 1);

    }

    @Override
    protected void defineSynchedData(SynchedEntityData.@NotNull Builder builder) {
        super.defineSynchedData(builder);
        builder.define(LEVEL, -1);
        builder.define(IS_CHARGING_CROSSBOW, false);
        builder.define(SPECIAL_ARROW, ModItems.QUARREL_NORMAL);
    }

    @Nullable
    @Override
    public SpawnGroupData finalizeSpawn(ServerLevelAccessor pLevel, DifficultyInstance pDifficulty, EntitySpawnReason pReason, @Nullable SpawnGroupData pSpawnData) {
        applySupporter(this, VampirismMod.services().supporterManager().getRandomHunter(random));
        return super.finalizeSpawn(pLevel, pDifficulty, pReason, pSpawnData);
    }

    @Override
    protected int getBaseExperienceReward(ServerLevel level) {
        this.xpReward = 10 * (1 + getEntityLevel());
        return super.getBaseExperienceReward(level);
    }

    @Override
    protected @NotNull EntityType<?> getIMobTypeOpt(boolean iMob) {
        return iMob ? ModEntities.ADVANCED_HUNTER_IMOB.get() : ModEntities.ADVANCED_HUNTER.get();
    }

    @NotNull
    @Override
    protected InteractionResult mobInteract(@NotNull Player player, @NotNull InteractionHand hand) { //processInteract
        if (hand == InteractionHand.MAIN_HAND && tryCureSanguinare(player)) return InteractionResult.SUCCESS;
        return super.mobInteract(player, hand);
    }

    @Nonnull
    @Override
    public ItemStack getProjectile(ItemStack stack) {
        if (stack.getItem() instanceof IHunterCrossbow) {
            Holder<Item> item = ModItems.QUARREL_NORMAL;
            if (random.nextFloat() < 0.2) {
                item = getEntityData().get(SPECIAL_ARROW);
            }
            return net.neoforged.neoforge.common.CommonHooks.getProjectile(this, stack, item.value().getDefaultInstance());
        }
        return super.getProjectile(stack);
    }

    @Override
    protected @NotNull PathNavigation createNavigation(@NotNull Level level) {
        return new HunterPathNavigation(this, level);
    }

    @Override
    protected void registerGoals() {
        super.registerGoals();

        this.goalSelector.addGoal(1, new OpenDoorGoal(this, true));
        this.goalSelector.addGoal(1, new OpenGateGoal(this, true));
        this.goalSelector.addGoal(2, new RangedHunterCrossbowAttackGoal<>(this, 0.8, 100));
        this.goalSelector.addGoal(3, new MeleeAttackGoal(this, 1.0, false));

        this.goalSelector.addGoal(6, new RandomStrollGoal(this, 0.7, 50));
        this.goalSelector.addGoal(8, new LookAtPlayerGoal(this, Player.class, 13F));
        this.goalSelector.addGoal(8, new LookAtPlayerGoal(this, VampireBaseEntity.class, 17F));
        this.goalSelector.addGoal(8, new RandomLookAroundGoal(this));

        this.targetSelector.addGoal(1, new HunterHurtByTargetGoal(this));
        this.targetSelector.addGoal(2, new AttackVillageGoal<>(this));
        this.targetSelector.addGoal(2, new DefendVillageGoal<>(this));//Should automatically be mutually exclusive with  attack village
        this.targetSelector.addGoal(3, new NearestAttackableTargetGoal<>(this, Player.class, 5, true, false, IFactionPredicate.defaultTargets(getFaction()).onlyPlayer().notNeutral().build()));
        this.targetSelector.addGoal(5, new NearestAttackableTargetGoal<>(this, PathfinderMob.class, 5, true, false, IFactionPredicate.defaultTargets(getFaction()).onlyNonPlayers().notNeutral().build()));
        this.targetSelector.addGoal(6, new NearestAttackableTargetGoal<>(this, Zombie.class, true, true));
        this.targetSelector.addGoal(7, new NearestAttackableTargetGoal<>(this, PatrollingMonster.class, 5, true, true, (living, level) -> UtilLib.isInsideStructure(living, StructureTags.VILLAGE)));
    }

    protected void updateEntityAttributes() {
        int l = Math.max(getEntityLevel(), 0);
        this.getAttribute(Attributes.MAX_HEALTH).setBaseValue(BalanceMobProps.mobProps.ADVANCED_HUNTER_MAX_HEALTH + BalanceMobProps.mobProps.ADVANCED_HUNTER_MAX_HEALTH_PL * l);
        this.getAttribute(Attributes.ATTACK_DAMAGE).setBaseValue(BalanceMobProps.mobProps.ADVANCED_HUNTER_ATTACK_DAMAGE + BalanceMobProps.mobProps.ADVANCED_HUNTER_ATTACK_DAMAGE_PL * l);
    }

