/**
 * Vampire that spawns in the vampire forest, has minions and drops pure blood
 */
public class VampireBaronEntity extends VampireBaseEntity implements IVampireBaron, IWingsEntity {
    public static final int MAX_LEVEL = 4;
    private static final EntityDataAccessor<Integer> LEVEL = SynchedEntityData.defineId(VampireBaronEntity.class, EntityDataSerializers.INT);
    private static final EntityDataAccessor<Boolean> ENRAGED = SynchedEntityData.defineId(VampireBaronEntity.class, EntityDataSerializers.BOOLEAN);
    private static final EntityDataAccessor<Boolean> LADY = SynchedEntityData.defineId(VampireBaronEntity.class, EntityDataSerializers.BOOLEAN);
    private static final EntityDataAccessor<WingsState> WINGS_STATE = SynchedEntityData.defineId(VampireBaronEntity.class, ModEntities.WINGS_STATE.get());

    public static boolean spawnPredicateBaron(EntityType<? extends VampireBaronEntity> entityType, LevelAccessor world, EntitySpawnReason spawnReason, BlockPos blockPos, RandomSource random) {
        return world.getBiome(blockPos).is(ModBiomeTags.HasFaction.IS_VAMPIRE_BIOME) && world.getDifficulty() != net.minecraft.world.Difficulty.PEACEFUL && Mob.checkMobSpawnRules(entityType, world, spawnReason, blockPos, random);
    }

    public static AttributeSupplier.Builder getAttributeBuilder() {
        return VampireBaseEntity.getAttributeBuilder()
                .add(Attributes.MAX_HEALTH, BalanceMobProps.mobProps.VAMPIRE_BARON_MAX_HEALTH)
                .add(Attributes.ATTACK_DAMAGE, BalanceMobProps.mobProps.VAMPIRE_BARON_ATTACK_DAMAGE)
                .add(Attributes.MOVEMENT_SPEED, BalanceMobProps.mobProps.VAMPIRE_BARON_MOVEMENT_SPEED)
                .add(Attributes.FOLLOW_RANGE, 5);
    }

    /**
     * Used for ranged vs melee attack decision
     */
    private int attackDecisionCounter = 0;
    /**
     * Whether to prefer ranged attack
     */
    private boolean rangedAttack = false;
    private boolean prevAttacking = false;
    /**
     * Store the approximate count of entities that are following this advanced vampire.
     * Not guaranteed to be exact and not saved to nbt
     */
    private int followingEntities = 0;

    public VampireBaronEntity(EntityType<? extends VampireBaronEntity> type, Level world) {
        super(type, world);
        this.garlicResist = EnumStrength.MEDIUM;
        this.hasArms = true;
    }

    @Override
    public void updateDataBeforeSync() {
        super.updateDataBeforeSync();
    }

    @Override
    public void onSyncedDataUpdated(EntityDataAccessor<?> key) {
        super.onSyncedDataUpdated(key);
        if (WINGS_STATE.equals(key)) {
            if (getWingsState() == WingsState.OPENING || getWingsState() == WingsState.CLOSING) {
                switchState(getWingsState());
            }
        }
    }

    private int growTicks = 0;
    private final AnimationState growAnimationState = new AnimationState();
    private final AnimationState idleAnimationState = new AnimationState();


    private void switchState(IWingsEntity.WingsState state) {
        this.setWingsState(state);
        this.growTicks = 0;
        switch (state) {
            case OPEN ->  {
                this.idleAnimationState.start(asEntity().tickCount);
                this.growAnimationState.stop();
            }
            case CLOSED -> {
                this.idleAnimationState.stop();
                this.growAnimationState.stop();
            }
            case OPENING, CLOSING -> {
                int startTicks = asEntity().tickCount;
                int currentTicks = this.growAnimationState.vampirism$startTick();
                if (currentTicks != Integer.MIN_VALUE) {
                    int div = startTicks - currentTicks;
                    if (div < IWingsEntity.GROW_TICKS) {
                        startTicks -= (int) IWingsEntity.GROW_TICKS - div;
                    }
                }
                this.growAnimationState.start(startTicks);
                this.idleAnimationState.stop();
            }
        }
    }

    @Override
    public boolean openWings() {
        switchState(WingsState.OPENING);
        return true;
    }

    @Override
    public void closeWings(boolean force) {
        switchState(force ? WingsState.CLOSED : WingsState.CLOSING);
    }

    @Override
    public void swingWings() {
        // vampire barons cannot fly
    }

    @Override
    public void toggleWings() {
        switch(getWingsState()) {
            case OPEN, OPENING, FLYING -> closeWings();
            case CLOSED, CLOSING -> openWings();
        }
    }

    @Override
    public AnimationState flyAnimationState() {
        return this.idleAnimationState;
    }

    @Override
    public AnimationState growAnimationState() {
        return this.growAnimationState;
    }

    @Override
    public WingsState getWingsState() {
        return this.entityData.get(WINGS_STATE);
    }

    public void setWingsState(WingsState state) {
        this.entityData.set(WINGS_STATE, state);
    }

    @Override
    public void tick() {
        super.tick();
        switch (getWingsState()) {
            case OPENING -> {
                if (growTicks++ > IWingsEntity.GROW_TICKS) {
                    switchState(WingsState.OPEN);
                }
            }
            case CLOSING -> {
                if (growTicks++ > IWingsEntity.GROW_TICKS) {
                    switchState(WingsState.CLOSED);
                }
            }
        }
        if (getWingsState() != WingsState.CLOSED) {
            updateAnimations();
        }
    }

    private void updateAnimations() {
        switch (this.getWingsState()) {
            case OPENING, CLOSING -> this.growAnimationState.startIfStopped(this.tickCount);
            case OPEN, FLYING -> this.idleAnimationState.startIfStopped(this.tickCount);
            case CLOSED -> {
                this.idleAnimationState.stop();
                this.growAnimationState.stop();
            }
        }
    }

    @Override
    public void addAdditionalSaveData(ValueOutput output) {
        super.addAdditionalSaveData(output);
        output.putInt("level", getEntityLevel());
        output.putBoolean("lady", isLady());
    }

    @Override
    public void aiStep() {
        if (!prevAttacking && this.getTarget() != null) {
            prevAttacking = true;
            updateEntityAttributes(true);
        }
        if (prevAttacking && this.getTarget() == null) {
            prevAttacking = false;
            this.rangedAttack = false;
            this.attackDecisionCounter = 0;
            updateEntityAttributes(false);
        }

        if (!this.level().isClientSide() && this.isGettingSundamage(level())) {
            this.teleportAway();

        }
        if (!this.level().isClientSide() && this.getTarget() != null && this.tickCount % 128 == 0) {
            if (rangedAttack) {
                if (this.random.nextInt(2) == 0 && this.navigation.createPath(this.getTarget(), 0) != null) {
                    rangedAttack = false;
                }
            } else {
                if (attackDecisionCounter > 4 || this.random.nextInt(6) == 0) {
                    rangedAttack = true;
                    attackDecisionCounter = 0;
                }
            }
            if (getEntityLevel() > 3 && this.random.nextInt(9) == 0) {
                this.addEffect(new MobEffectInstance(MobEffects.INVISIBILITY, 60));
            }
        }
        super.aiStep();
    }

    @Override
    public boolean checkSpawnRules(LevelAccessor worldIn, EntitySpawnReason spawnReasonIn) {
        int i = Mth.floor(this.getBoundingBox().minY);
        //Only spawn on the surface
        if (i < 60) return false;
        BlockPos blockpos = new BlockPos((int) this.getX(), (int) this.getBoundingBox().minY, (int) this.getZ());
        return worldIn.getBlockState(blockpos.below()).is(ModBlockTags.CURSED_EARTH) && super.checkSpawnRules(worldIn, spawnReasonIn);
    }

    @Override
    public void decreaseFollowerCount() {
        followingEntities = Math.max(0, followingEntities - 1);
    }

    @Override
    public boolean doHurtTarget(ServerLevel level, Entity entity) {
        boolean flag = super.doHurtTarget(level, entity);
        if (flag && entity instanceof LivingEntity) {
            float tm = 1f;
            int mr = 1;
            if (entity instanceof Player player) {
                float pld = (this.getEntityLevel() + 1) - VampirePlayer.get(player).getLevel() / 3f;
                tm = pld + 1;
                mr = pld < 1.5f ? 1 : (pld < 3 ? 2 : 3);
                if (HunterPlayer.get(player).getSpecialAttributes().fullHunterCoat != null) {
                    tm *= 0.5F;
                }
            }
            if (entity instanceof VampireBaronEntity) {
                ((LivingEntity) entity).addEffect(new MobEffectInstance(MobEffects.STRENGTH, 40, 5));
            }
            ((LivingEntity) entity).addEffect(new MobEffectInstance(MobEffects.WEAKNESS, (int) (200 * tm), random.nextInt(mr)));
            ((LivingEntity) entity).addEffect(new MobEffectInstance(MobEffects.SLOWNESS, (int) (100 * tm), random.nextInt(mr)));
            attackDecisionCounter = 0;
        }
        return flag;
    }

    @Nullable
    @Override
    public SpawnGroupData finalizeSpawn(ServerLevelAccessor worldIn, DifficultyInstance difficultyIn, EntitySpawnReason reason, @Nullable SpawnGroupData spawnDataIn) {
        this.getEntityData().set(LADY, this.getRandom().nextBoolean());
        return super.finalizeSpawn(worldIn, difficultyIn, reason, spawnDataIn);
    }

    @Override
    public int getFollowingCount() {
        return followingEntities;
    }

    @Override
    public int getEntityLevel() {
        return getEntityData().get(LEVEL);
    }

    @Override
    public void setEntityLevel(int level) {
        if (level >= 0) {
            getEntityData().set(LEVEL, level);
            this.updateEntityAttributes(false);
            float hp = this.getHealth() / this.getMaxHealth();
            this.setHealth(this.getMaxHealth() * hp);
            this.setCustomName(Component.translatable("entity.vampirism.vampire_baron.leveled", level + 1));
        } else {
            this.setCustomName(null);
        }
    }

    @Override
    public int getMaxHeadXRot() {
        return 5; //Turn around slowly
    }

    @Override
    public int getMaxFollowerCount() {
        return (int) (BalanceMobProps.mobProps.ADVANCED_VAMPIRE_MAX_FOLLOWER * this.getEntityLevel() / (float) this.getMaxEntityLevel() * 2f);
    }

    @Override
    public int getMaxHeadYRot() {
        return 5; //Don't move the head too far
    }

    @Override
    public int getMaxEntityLevel() {
        return MAX_LEVEL;
    }

    @Override
    public int getDimensionChangingDelay() {
        return 500;
    }

    @Override
    public boolean increaseFollowerCount() {
        if (followingEntities < getMaxFollowerCount()) {
            followingEntities++;
            return true;
        }
        return false;
    }

    @Override
    public boolean hurtServer(ServerLevel level, DamageSource damageSource, float amount) {
        attackDecisionCounter++;
        return super.hurtServer(level, damageSource, amount);
    }

    public boolean isEnraged() {
        return getEntityData().get(ENRAGED);
    }

    public boolean isLady() {
        return getEntityData().get(LADY);
    }

    public void setLady(boolean lady) {
        getEntityData().set(LADY, lady);
    }

    @Override
    public boolean killedEntity(ServerLevel world, LivingEntity entity, DamageSource damageSource) {
        boolean result = super.killedEntity(world, entity, damageSource);
        if (entity instanceof VampireBaronEntity) {
            this.setHealth(this.getMaxHealth());
        }
        return result;
    }

    @Override
    public void readAdditionalSaveData(ValueInput input) {
        super.readAdditionalSaveData(input);
        input.getInt("level").map(x -> Mth.clamp(x, 0, MAX_LEVEL)).ifPresent(this::setEntityLevel);
        this.getEntityData().set(LADY, input.getBooleanOr("lady", false));
    }

    @Override
    public void setTarget(@Nullable LivingEntity target) {
        var prev = this.getTarget();
        super.setTarget(target);
        this.getEntityData().set(ENRAGED, target != null);
        if (prev != getTarget()) {
            if (target != null) {
                openWings();
            } else {
                closeWings();
            }
        }
    }

    @Override
    public boolean shouldShowName() {
        return true;
    }

    @Override
    public int suggestEntityLevel(Difficulty d) {
        //Currently, this is not called when the entity is spawned by a command or spawn egg  to guarantee a spawn-> See finalizeSpawn

        //We want to distribute the baron levels between player levels 5 (from here on you need pure blood for leveling and 14 {@link de.teamlapen.vampirism.REFERENCE.HIGHEST_VAMPIRE_LEVEL}
        int avg = Math.round(((d.avgPercLevel() / 100f - 5 / 14f) / (1F - 5 / 14F)) * MAX_LEVEL);
        int max = Math.round(((d.maxPercLevel() / 100f - 5 / 14f) / (1F - 5 / 14F)) * MAX_LEVEL);
        int min = Math.round(((d.minPercLevel() / 100f - 5 / 14f) / (1F - 5 / 14F)) * MAX_LEVEL);
        //Values may be <0 leading to entity spawn being canceled
        return switch (random.nextInt(7)) {
            case 0 -> min;
            case 1 -> max + 1;
            case 2 -> avg;
            case 3 -> avg + 1;
            case 4, 5 -> random.nextInt(MAX_LEVEL + 1);
            default -> random.nextInt(max - min + 2) + min; //Even if values are negative max> min -> argument is >=2)
        };
    }

    @Override
    protected float calculateFireDamage(float amount) {
        return (float) (amount * BalanceMobProps.mobProps.VAMPIRE_BARON_FIRE_VULNERABILITY);
    }

    @Override
    protected void defineSynchedData(SynchedEntityData.Builder builder) {
        super.defineSynchedData(builder);
        builder.define(LEVEL, -1);
        builder.define(ENRAGED, false);
        builder.define(LADY, false);
        builder.define(WINGS_STATE, WingsState.CLOSED);
    }

    @Override
    protected int getBaseExperienceReward(ServerLevel level) {
        this.xpReward = 20 + 5 * getEntityLevel();
        return super.getBaseExperienceReward(level);
    }

    @Override
    protected void registerGoals() {
        super.registerGoals();
        this.goalSelector.addGoal(4, new FleeGarlicVampireGoal(this, 0.9F, false));
        this.goalSelector.addGoal(5, new BaronAIAttackMelee(this, 1.0F));
        this.goalSelector.addGoal(6, new BaronAIAttackRanged(this, 60, 64, 6, 4));
        this.goalSelector.addGoal(6, new AvoidEntityGoal<>(this, Player.class, 6.0F, 0.6, 0.7F, (input) -> !isLowerLevel(input, input.level())));//Works only partially. Pathfinding somehow does not find escape routes
        this.goalSelector.addGoal(7, new RandomStrollGoal(this, 0.2));
        this.goalSelector.addGoal(9, new LookAtClosestVisibleGoal(this, Player.class, 10.0F));
        this.goalSelector.addGoal(10, new RandomLookAroundGoal(this));

        this.targetSelector.addGoal(1, new HurtByTargetGoal(this));
        this.targetSelector.addGoal(2, new NearestAttackableTargetGoal<>(this, Player.class, 10, true, false, this::isLowerLevel));
        this.targetSelector.addGoal(3, new NearestAttackableTargetGoal<>(this, VampireBaronEntity.class, true, false));
    }

    protected void updateEntityAttributes(boolean aggressive) {
        if (aggressive) {
            this.getAttribute(Attributes.FOLLOW_RANGE).setBaseValue(20D);
            this.getAttribute(Attributes.MOVEMENT_SPEED).setBaseValue(BalanceMobProps.mobProps.VAMPIRE_BARON_MOVEMENT_SPEED * Math.pow((BalanceMobProps.mobProps.VAMPIRE_BARON_IMPROVEMENT_PER_LEVEL - 1) / 5 + 1, (getEntityLevel())));
        } else {
            this.getAttribute(Attributes.FOLLOW_RANGE).setBaseValue(5D);
            this.getAttribute(Attributes.MOVEMENT_SPEED).setBaseValue(BalanceMobProps.mobProps.VAMPIRE_BARON_MOVEMENT_SPEED * Math.pow(BalanceMobProps.mobProps.VAMPIRE_BARON_IMPROVEMENT_PER_LEVEL, getEntityLevel()) / 3);
        }
        float healthPercentage = getHealth() / getMaxHealth();
        this.getAttribute(Attributes.MAX_HEALTH).setBaseValue(BalanceMobProps.mobProps.VAMPIRE_BARON_MAX_HEALTH * Math.pow(BalanceMobProps.mobProps.VAMPIRE_BARON_IMPROVEMENT_PER_LEVEL, getEntityLevel()));
        setHealth(healthPercentage * getMaxHealth());
        this.getAttribute(Attributes.ATTACK_DAMAGE).setBaseValue(BalanceMobProps.mobProps.VAMPIRE_BARON_ATTACK_DAMAGE * Math.pow(BalanceMobProps.mobProps.VAMPIRE_BARON_IMPROVEMENT_PER_LEVEL, getEntityLevel()));
    }

    private boolean isLowerLevel(LivingEntity player, Level level) {
        if (player instanceof Player) {
            int playerLevel = FactionPlayerHandler.get((Player) player).getCurrentLevel();
            return (playerLevel - 8) / 2F - VampireBaronEntity.this.getEntityLevel() <= 0;
        }
        return false;
    }

    @Override
    protected boolean canRide(Entity pVehicle) {
        return false;
    }

    private class BaronAIAttackMelee extends MeleeAttackGoal {

        BaronAIAttackMelee(PathfinderMob creature, double speedIn) {
            super(creature, speedIn, false);
        }

        @Override
        public boolean canContinueToUse() {
            return !VampireBaronEntity.this.rangedAttack && super.canContinueToUse();
        }

        @Override
        public boolean canUse() {
            return !VampireBaronEntity.this.rangedAttack && super.canUse();
        }
    }

    private class BaronAIAttackRanged extends AttackRangedDarkBloodGoal {

        BaronAIAttackRanged(VampireBaronEntity entity, int cooldown, int maxDistance, float damage, float indirectDamage) {
            super(entity, cooldown, maxDistance, damage, indirectDamage);
        }

        @Override
        public boolean canUse() {
            return VampireBaronEntity.this.getTarget() != null && (VampireBaronEntity.this.rangedAttack || !VampireBaronEntity.this.isPathFinding());
        }
    }
}

